#[cfg(test)]mod appearance27_animator_binding_development_tests {
 use super::*;
 use super::super::native_world::World;
 fn world()->World{let mut w=super::super::native_login::LoginController::default().snapshot().world.clone();let f:serde_json::Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for k in["world","start","status","actor","bot"]{let h=f["packets"][k].as_str().unwrap();w.accept(&(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect::<Vec<_>>()).unwrap();}let id=w.own_actor().unwrap().id;let a=w.actors.get_mut(&id).unwrap();a.graphics=100;a.walk_action=0;a.speed=0;a.brave=0;a.motion_from=None;w}
 fn catalog()->SpriteActionCatalog{SpriteActionCatalog::parse_for_inspection(b"11297 0 0\n#100 16 old 0.walk(1 2,0.0:12 0.1:12) 3.idle(1 2,8.0:12 8.1:12) 8.dead(1 2,24.0:12 24.1:12) 18.cast(1 2,16.0:12! 16.1:12[88) 19.cast(1 2,32.0:12 32.1:12) 101.shadow(200)\n#101 16 new 4.walk(1 2,0.0:12 0.1:12) 7.idle(1 2,8.0:12 8.1:12) 8.dead(1 2,24.0:12 24.1:12) 18.cast(1 2,16.0:12 16.1:12) 19.cast(1 2,32.0:12[9 32.1:12) 101.shadow(201)\n#200 16 old shadow\n#201 16 new shadow\n",super::super::sprite_actions::ActionLimits::default()).unwrap()}
 fn action(w:&mut World,value:u8){let mut b=vec![32];b.extend(w.own_actor().unwrap().id.to_le_bytes());b.push(value);w.accept(&b).unwrap();}
 fn shape(w:&mut World,gfx:u16,family:u8){let mut b=vec![39];b.extend(w.own_actor().unwrap().id.to_le_bytes());b.extend(gfx.to_le_bytes());b.push(family);w.accept(&b).unwrap();}
 fn animator(w:&World)->Animator{let mut a=Animator::default();a.select_appearance_context(7,w.generation,w.map_id.unwrap());a}
 #[test]fn busy_cast_keeps_old_logical_body_and_new_cast_waits_after_queued_shape(){let mut w=world();let c=catalog();let mut a=animator(&w);action(&mut w,18);let p=a.pose(&c,w.own_actor().unwrap(),0).unwrap();assert_eq!(p.logical_graphics,100);shape(&mut w,101,4);action(&mut w,19);let p=a.pose(&c,w.own_actor().unwrap(),100_000_000).unwrap();assert_eq!(p.logical_graphics,100);assert_eq!(p.family,0);let p=a.pose(&c,w.own_actor().unwrap(),1_000_000_000).unwrap();assert_eq!((p.logical_graphics,p.family,p.phase),(101,4,"idle"));assert_eq!(p.body_callback_millis,Some(1584));let p=a.pose(&c,w.own_actor().unwrap(),1_583_000_000).unwrap();assert_eq!(p.phase,"idle");assert_eq!(p.body_pending,1);let p=a.pose(&c,w.own_actor().unwrap(),1_584_000_000).unwrap();assert_eq!((p.logical_graphics,p.action),(101,19));assert_eq!(p.entered_events.iter().filter(|e|e.sound==Some(9)).count(),1);}
 #[test]fn idle_shape_is_direct_and_uses_new_logical_layers_in_the_same_poll(){let mut w=world();let c=catalog();let mut a=animator(&w);a.pose(&c,w.own_actor().unwrap(),0).unwrap();shape(&mut w,101,4);action(&mut w,19);let p=a.pose(&c,w.own_actor().unwrap(),100_000_000).unwrap();assert_eq!((p.logical_graphics,p.family,p.action),(101,4,19));assert!(p.body_callback_millis.is_none());let bindings=super::super::native_actor_layers::Plan::from_catalog(&c,u32::from(p.logical_graphics)).unwrap().bind(p.image).unwrap();assert!(bindings.shadow.as_deref().unwrap().starts_with("201-"));}
 #[test]fn active_walk_keeps_old_motion_and_family_until_its_boundary(){let mut w=world();let c=catalog();let id=w.own_actor().unwrap().id;{let a=w.actors.get_mut(&id).unwrap();a.x=100;a.y=100;a.motion_from=Some([99,100]);a.motion_revision+=1;}let mut a=animator(&w);a.pose(&c,w.own_actor().unwrap(),0).unwrap();shape(&mut w,101,4);let p=a.pose(&c,w.own_actor().unwrap(),500_000_000).unwrap();assert_eq!((p.logical_graphics,p.phase),(100,"walk"));assert_eq!(p.position,[99.5,100.]);let p=a.pose(&c,w.own_actor().unwrap(),1_000_000_000).unwrap();assert_eq!((p.logical_graphics,p.phase),(101,"idle"));assert_eq!(p.position,[100.,100.]);}
 #[test]fn death_holds_old_body_and_new_life_retires_pending_shape_without_reviving(){let mut w=world();let c=catalog();let mut a=animator(&w);action(&mut w,8);a.pose(&c,w.own_actor().unwrap(),0).unwrap();shape(&mut w,101,4);let p=a.pose(&c,w.own_actor().unwrap(),5_000_000_000).unwrap();assert_eq!((p.logical_graphics,p.phase),(100,"death"));assert!(w.own_actor().unwrap().dead);assert_eq!(p.body_pending,1);let id=w.own_actor().unwrap().id;let mut b=vec![17];b.extend(id.to_le_bytes());b.push(4);b.extend(2_u32.to_le_bytes());b.extend(101_u16.to_le_bytes());w.accept(&b).unwrap();let p=a.pose(&c,w.own_actor().unwrap(),6_000_000_000).unwrap();assert_eq!((p.logical_graphics,p.phase),(101,"idle"));assert_eq!(p.body_pending,0);}
 #[test]fn same_source_history_keeps_cursor_and_root_aba_never_imports_worker_graph(){let mut w=world();let c=catalog();let mut a=animator(&w);action(&mut w,18);a.pose(&c,w.own_actor().unwrap(),0).unwrap();shape(&mut w,101,4);action(&mut w,19);a.pose(&c,w.own_actor().unwrap(),100_000_000).unwrap();let h=a.history();let mut same=Animator::default();same.restore(h.clone());same.select_appearance_context(7,w.generation,w.map_id.unwrap());let mut admitted=Admission::default();admitted.admit(&w);same.retire_admitted(admitted,&w,200_000_000);assert_eq!(same.pose(&c,w.own_actor().unwrap(),200_000_000).unwrap().logical_graphics,100);assert_eq!(same.pose(&c,w.own_actor().unwrap(),500_000_000).unwrap().entered_events.iter().filter(|e|e.sound==Some(88)).count(),1);let mut retired=h.for_source(false);retired.merge_late(&same.history());let mut fresh=Animator::default();fresh.restore(retired.for_source(true));fresh.select_appearance_context(7,w.generation,w.map_id.unwrap());let p=fresh.pose(&c,w.own_actor().unwrap(),300_000_000).unwrap();assert_eq!((p.logical_graphics,p.phase,p.body_pending),(101,"idle",0));assert!(p.entered_events.is_empty());}
 #[test]fn late_callback_reschedules_from_actual_poll_and_does_not_catch_up(){let mut w=world();let c=catalog();let mut a=animator(&w);action(&mut w,18);a.pose(&c,w.own_actor().unwrap(),0).unwrap();shape(&mut w,101,4);action(&mut w,19);a.pose(&c,w.own_actor().unwrap(),100_000_000).unwrap();let p=a.pose(&c,w.own_actor().unwrap(),9_000_000_000).unwrap();assert_eq!(p.body_callback_millis,Some(9584));assert_eq!(p.phase,"idle");assert!(a.pose(&c,w.own_actor().unwrap(),9_583_000_000).unwrap().entered_events.is_empty());assert_eq!(a.pose(&c,w.own_actor().unwrap(),9_584_000_000).unwrap().action,19);}
 #[test]fn unbound_lt_never_aliases_a_shared_sprite_or_mutates_authority(){let mut w=world();let c=catalog();let mut a=animator(&w);a.pose(&c,w.own_actor().unwrap(),0).unwrap();shape(&mut w,30001,4);let before=serde_json::to_value(&w).unwrap();assert!(a.pose(&c,w.own_actor().unwrap(),100_000_000).is_err());assert_eq!(serde_json::to_value(&w).unwrap(),before);}
}
